import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { toast } from 'react-toastify';

export default function CoursePlayerPage() {
  const { courseId } = useParams();
  const navigate = useNavigate();
  const [course, setCourse] = useState(null);
  const [progress, setProgress] = useState([]);
  const [completionPct, setCompletionPct] = useState(0);
  const [activeLesson, setActiveLesson] = useState(null);
  const [activeModule, setActiveModule] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [quiz, setQuiz] = useState(null);
  const [quizAnswers, setQuizAnswers] = useState({});
  const [quizResult, setQuizResult] = useState(null);
  const [certLoading, setCertLoading] = useState(false);
  const [cert, setCert] = useState(null);
  const videoRef = useRef(null);

  useEffect(() => {
    const load = async () => {
      try {
        const [courseRes, progressRes] = await Promise.all([
          axios.get(`/api/courses/${courseId}`),
          axios.get(`/api/progress/course/${courseId}`)
        ]);
        setCourse(courseRes.data);
        setProgress(progressRes.data.progress || []);
        setCompletionPct(progressRes.data.completionPercentage || 0);
        // Set first lesson
        if (courseRes.data.modules?.[0]?.lessons?.[0]) {
          setActiveLesson(courseRes.data.modules[0].lessons[0]);
          setActiveModule(courseRes.data.modules[0]);
        }
      } catch { navigate('/dashboard'); }
    };
    load();
  }, [courseId]);

  const isLessonDone = (lessonId) => progress.some(p => p.lesson?.toString() === lessonId?.toString() && p.isCompleted);

  const markComplete = async () => {
    if (!activeLesson || !activeModule) return;
    if (isLessonDone(activeLesson._id)) { toast.info('Already completed!'); return; }
    try {
      const { data } = await axios.post('/api/progress/lesson', {
        courseId, moduleId: activeModule._id, lessonId: activeLesson._id, watchedSeconds: 60
      });
      setProgress(prev => [...prev, { lesson: activeLesson._id, isCompleted: true }]);
      setCompletionPct(data.completionPercentage);
      toast.success(`✅ +10 XP! ${data.completionPercentage}% complete`);
      if (data.completionPercentage === 100) toast.success('🎉 Course completed! Generate your certificate!');
    } catch (err) { toast.error('Error marking complete'); }
  };

  const loadQuiz = async () => {
    try {
      const { data } = await axios.get(`/api/quizzes/course/${courseId}`);
      if (data.length) { setQuiz(data[0]); setQuizResult(null); setQuizAnswers({}); }
      else toast.info('No quizzes for this course yet');
    } catch { toast.error('Could not load quiz'); }
  };

  const submitQuiz = async () => {
    const answers = quiz.questions.map((_, i) => quizAnswers[i] ?? -1);
    try {
      const { data } = await axios.post(`/api/quizzes/${quiz._id}/attempt`, { answers });
      setQuizResult(data);
    } catch { toast.error('Quiz submission failed'); }
  };

  const generateCert = async () => {
    setCertLoading(true);
    try {
      const { data } = await axios.post(`/api/certificates/generate/${courseId}`);
      setCert(data);
      toast.success('🏆 Certificate generated!');
    } catch (err) { toast.error(err.response?.data?.message || 'Cannot generate certificate yet'); }
    setCertLoading(false);
  };

  const selectLesson = (mod, lesson) => { setActiveModule(mod); setActiveLesson(lesson); setQuiz(null); setQuizResult(null); };
  const completedCount = progress.filter(p => p.isCompleted).length;
  const totalLessons = course?.modules?.reduce((a, m) => a + m.lessons.length, 0) || 0;

  if (!course) return <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: '100vh' }}><div className="loader" /></div>;

  return (
    <div style={{ height: '100vh', display: 'flex', flexDirection: 'column', paddingTop: 70, background: '#03020a' }}>
      {/* Top bar */}
      <div style={{ height: 56, background: 'rgba(8,6,20,0.95)', borderBottom: '1px solid rgba(124,58,237,0.2)', display: 'flex', alignItems: 'center', padding: '0 20px', gap: 16, flexShrink: 0 }}>
        <button onClick={() => navigate('/dashboard')} style={{ background: 'none', border: 'none', color: '#b8b0d8', cursor: 'pointer', fontSize: 14, display: 'flex', alignItems: 'center', gap: 6 }}>
          ← Back
        </button>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontWeight: 700, fontSize: 14, color: '#f0eeff', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{course.title}</div>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 13 }}>
            <div style={{ width: 120, height: 6, background: 'rgba(124,58,237,0.2)', borderRadius: 3, overflow: 'hidden' }}>
              <div style={{ height: '100%', width: `${completionPct}%`, background: 'linear-gradient(90deg, #7c3aed, #00f5d4)', borderRadius: 3, transition: 'width 0.6s ease' }} />
            </div>
            <span style={{ color: '#c084fc', fontWeight: 700 }}>{completionPct}%</span>
          </div>
          <span style={{ fontSize: 12, color: '#6b6490' }}>{completedCount}/{totalLessons}</span>
          {completionPct === 100 && (
            <button className="btn btn-primary btn-sm" onClick={generateCert} disabled={certLoading}>
              {certLoading ? '...' : '🏆 Get Certificate'}
            </button>
          )}
        </div>
        <button onClick={() => setSidebarOpen(s => !s)} style={{ background: 'rgba(124,58,237,0.15)', border: '1px solid rgba(124,58,237,0.3)', borderRadius: 8, color: '#c084fc', cursor: 'pointer', padding: '6px 12px', fontSize: 13, fontWeight: 600 }}>
          {sidebarOpen ? '☰ Hide' : '☰ Curriculum'}
        </button>
      </div>

      {/* Main area */}
      <div style={{ flex: 1, display: 'flex', overflow: 'hidden' }}>
        {/* Video + Content */}
        <div style={{ flex: 1, overflow: 'auto', display: 'flex', flexDirection: 'column' }}>
          {/* Video Area */}
          <div style={{ background: '#000', position: 'relative', aspectRatio: '16/9', maxHeight: '55vh' }}>
            {activeLesson?.videoUrl ? (
              <video ref={videoRef} controls style={{ width: '100%', height: '100%', display: 'block' }}
                src={`http://localhost:5000/${activeLesson.videoUrl}`} />
            ) : (
              <div style={{ width: '100%', height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', background: 'linear-gradient(135deg, #0e0b1e, #14112a)', color: '#6b6490' }}>
                <div style={{ fontSize: 72, marginBottom: 16 }}>📄</div>
                <div style={{ fontSize: 18, fontWeight: 700, color: '#b8b0d8' }}>Text Lesson</div>
                <div style={{ fontSize: 14, marginTop: 8 }}>No video for this lesson</div>
              </div>
            )}
          </div>

          {/* Lesson Info */}
          <div style={{ padding: '28px 32px', flex: 1 }}>
            {activeLesson ? (
              <>
                <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 16, marginBottom: 16, flexWrap: 'wrap' }}>
                  <div>
                    <h1 style={{ fontSize: 24, fontWeight: 800, color: '#f0eeff', marginBottom: 8 }}>{activeLesson.title}</h1>
                    <div style={{ fontSize: 14, color: '#6b6490' }}>{activeModule?.title}</div>
                  </div>
                  <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
                    {isLessonDone(activeLesson._id) ? (
                      <div style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '10px 20px', borderRadius: 10, background: 'rgba(0,245,212,0.1)', border: '1px solid rgba(0,245,212,0.3)', color: '#00f5d4', fontWeight: 700, fontSize: 14 }}>
                        ✓ Completed
                      </div>
                    ) : (
                      <button className="btn btn-primary" onClick={markComplete}>✓ Mark Complete</button>
                    )}
                    <button className="btn btn-ghost" onClick={loadQuiz}>📝 Take Quiz</button>
                  </div>
                </div>
                {activeLesson.description && (
                  <div style={{ padding: 24, background: 'rgba(124,58,237,0.06)', borderRadius: 14, border: '1px solid rgba(124,58,237,0.15)', marginBottom: 24 }}>
                    <p style={{ fontSize: 15, color: '#b8b0d8', lineHeight: 1.7 }}>{activeLesson.description}</p>
                  </div>
                )}
                {activeLesson.resources?.length > 0 && (
                  <div>
                    <h3 style={{ fontSize: 16, fontWeight: 700, marginBottom: 12, color: '#f0eeff' }}>Resources</h3>
                    {activeLesson.resources.map((r, i) => (
                      <a key={i} href={r.url} target="_blank" rel="noreferrer" style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '10px 16px', borderRadius: 10, background: 'rgba(124,58,237,0.08)', border: '1px solid rgba(124,58,237,0.2)', color: '#c084fc', textDecoration: 'none', marginBottom: 8, fontSize: 14, fontWeight: 600 }}>
                        📎 {r.name}
                      </a>
                    ))}
                  </div>
                )}
              </>
            ) : (
              <div style={{ textAlign: 'center', color: '#6b6490', padding: 40 }}>Select a lesson to begin</div>
            )}

            {/* Quiz Panel */}
            {quiz && (
              <div className="glass" style={{ padding: 28, borderRadius: 16, marginTop: 24 }}>
                <h2 style={{ fontSize: 20, fontWeight: 800, marginBottom: 20, color: '#f0eeff' }}>📝 {quiz.title}</h2>
                {!quizResult ? (
                  <>
                    {quiz.questions.map((q, qi) => (
                      <div key={qi} style={{ marginBottom: 24 }}>
                        <div style={{ fontSize: 15, fontWeight: 700, color: '#f0eeff', marginBottom: 12 }}>{qi + 1}. {q.question}</div>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                          {q.options.map((opt, oi) => (
                            <button key={oi} onClick={() => setQuizAnswers(a => ({ ...a, [qi]: oi }))} style={{
                              padding: '11px 16px', borderRadius: 10, border: `1px solid ${quizAnswers[qi] === oi ? '#7c3aed' : 'rgba(124,58,237,0.2)'}`,
                              background: quizAnswers[qi] === oi ? 'rgba(124,58,237,0.2)' : 'transparent',
                              color: quizAnswers[qi] === oi ? '#c084fc' : '#b8b0d8',
                              cursor: 'pointer', textAlign: 'left', fontSize: 14, fontWeight: quizAnswers[qi] === oi ? 600 : 400,
                              transition: 'all 0.2s'
                            }}>{opt}</button>
                          ))}
                        </div>
                      </div>
                    ))}
                    <button className="btn btn-primary" onClick={submitQuiz}
                      disabled={Object.keys(quizAnswers).length < quiz.questions.length}>
                      Submit Quiz
                    </button>
                  </>
                ) : (
                  <div style={{ textAlign: 'center', padding: '20px 0' }}>
                    <div style={{ fontSize: 64, marginBottom: 12 }}>{quizResult.passed ? '🎉' : '😔'}</div>
                    <div style={{ fontSize: 36, fontWeight: 900, color: quizResult.passed ? '#00f5d4' : '#f72585', marginBottom: 8 }}>{quizResult.score}%</div>
                    <div style={{ fontSize: 16, color: '#b8b0d8', marginBottom: 8 }}>{quizResult.passed ? 'Passed! Great job!' : 'Not quite — try again!'}</div>
                    <div style={{ fontSize: 14, color: '#6b6490', marginBottom: 20 }}>{quizResult.correct}/{quizResult.total} correct</div>
                    <button className="btn btn-ghost" onClick={() => { setQuizResult(null); setQuizAnswers({}); }}>Retry Quiz</button>
                  </div>
                )}
              </div>
            )}

            {/* Certificate */}
            {cert && (
              <div className="glass" style={{ padding: 28, borderRadius: 16, marginTop: 24, border: '1px solid rgba(255,215,0,0.3)', background: 'rgba(255,215,0,0.05)', textAlign: 'center' }}>
                <div style={{ fontSize: 48, marginBottom: 12 }}>🏆</div>
                <h3 style={{ fontSize: 20, fontWeight: 800, color: '#ffd700', marginBottom: 8 }}>Certificate Ready!</h3>
                <div style={{ fontSize: 14, color: '#b8b0d8', marginBottom: 16 }}>ID: {cert.certificateId}</div>
                <a href={`http://localhost:5000/api/certificates/download/${cert.certificateId}`}
                  className="btn btn-primary" style={{ textDecoration: 'none' }}>
                  ⬇️ Download Certificate PDF
                </a>
              </div>
            )}
          </div>
        </div>

        {/* Sidebar */}
        {sidebarOpen && (
          <div style={{ width: 320, background: 'rgba(8,6,20,0.95)', borderLeft: '1px solid rgba(124,58,237,0.15)', overflow: 'auto', flexShrink: 0 }}>
            <div style={{ padding: '16px 20px', borderBottom: '1px solid rgba(124,58,237,0.15)' }}>
              <div style={{ fontSize: 13, fontWeight: 700, color: '#c084fc', marginBottom: 6 }}>COURSE CONTENT</div>
              <div className="progress-bar">
                <div className="progress-fill" style={{ width: `${completionPct}%` }} />
              </div>
            </div>
            {course.modules?.map((mod, mi) => (
              <div key={mod._id} style={{ borderBottom: '1px solid rgba(124,58,237,0.08)' }}>
                <div style={{ padding: '14px 20px', fontWeight: 700, fontSize: 13, color: '#f0eeff', background: 'rgba(124,58,237,0.05)' }}>
                  {mi + 1}. {mod.title}
                  <span style={{ display: 'block', fontSize: 11, color: '#6b6490', fontWeight: 400, marginTop: 2 }}>
                    {mod.lessons.filter(l => isLessonDone(l._id)).length}/{mod.lessons.length} done
                  </span>
                </div>
                {mod.lessons.map((lesson, li) => {
                  const done = isLessonDone(lesson._id);
                  const isActive = activeLesson?._id === lesson._id;
                  return (
                    <button key={lesson._id} onClick={() => selectLesson(mod, lesson)} style={{
                      width: '100%', padding: '11px 20px 11px 28px', background: isActive ? 'rgba(124,58,237,0.15)' : 'none',
                      border: 'none', borderLeft: isActive ? '3px solid #7c3aed' : '3px solid transparent',
                      color: done ? '#00f5d4' : '#b8b0d8', cursor: 'pointer',
                      textAlign: 'left', fontSize: 13, display: 'flex', alignItems: 'center', gap: 10,
                      transition: 'all 0.2s',
                    }}>
                      <span style={{ fontSize: 16, flexShrink: 0 }}>{done ? '✅' : lesson.videoUrl ? '🎬' : '📄'}</span>
                      <span style={{ flex: 1, lineHeight: 1.4, fontWeight: isActive ? 600 : 400 }}>{lesson.title}</span>
                    </button>
                  );
                })}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
